package live.linghe.privateinput;
import android.app.Instrumentation;import android.content.*;import android.net.Uri;import android.os.*;
/** Real SDK ClipData snapshots; test UID, no system clipboard or network access. */
public final class ClipboardCandidateCheck extends Instrumentation {
 int checks;void require(boolean v,String why){checks++;if(!v)throw new AssertionError(why);}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();try{
  require(getTargetContext().getPackageName().equals("live.linghe.privateinput.tests"),"isolated UID");String raw="  first\r\n\tsecond\n\nlast 😀  ";ClipData plain=ClipData.newPlainText("synthetic",raw);ClipboardCandidateState.Value value=ClipboardCandidateReader.decode(plain);require(value!=null&&value.raw.equals(raw),"native ClipData preserves all raw formatting");
  PersistableBundle extras=new PersistableBundle();extras.putBoolean("android.content.extra.IS_SENSITIVE",true);ClipData sensitive=ClipData.newPlainText("synthetic","sensitive");sensitive.getDescription().setExtras(extras);require(ClipboardCandidateReader.decode(sensitive)==null,"sensitive returned snapshot denied even if earlier description was ordinary");
  ClipData multiple=ClipData.newPlainText("synthetic","a");multiple.addItem(new ClipData.Item("b"));require(ClipboardCandidateReader.decode(multiple)==null,"multiple items excluded");ClipData uri=new ClipData("synthetic",new String[]{ClipDescription.MIMETYPE_TEXT_PLAIN},new ClipData.Item(Uri.parse("content://synthetic.invalid/value")));require(ClipboardCandidateReader.decode(uri)==null,"URI is never coerced into body");ClipData intent=new ClipData("synthetic",new String[]{ClipDescription.MIMETYPE_TEXT_PLAIN},new ClipData.Item(new Intent("synthetic.invalid")));require(ClipboardCandidateReader.decode(intent)==null,"Intent excluded");require(ClipboardCandidateReader.decode(new ClipData("synthetic",new String[]{"image/png"},new ClipData.Item("text")))==null,"nonplain description excluded");require(ClipboardCandidateReader.decode(ClipData.newPlainText("synthetic","\ud800"))==null,"malformed scalar excluded");require(ClipboardCandidateReader.decode(null)==null,"denied or empty snapshot excluded");
  runOnMainSync(()->{java.util.concurrent.atomic.AtomicReference<String> accepted=new java.util.concurrent.atomic.AtomicReference<>();SharedTextEntry entry=new SharedTextEntry(getTargetContext(),raw,"复制",accepted::set);android.widget.TextView body=(android.widget.TextView)entry.getChildAt(0);require(body.getText().toString().equals(raw),"native shared text retains exact raw CRLF/tabs/newlines/spaces");require(body.isTextSelectable(),"shared body supports native selection");entry.measure(android.view.View.MeasureSpec.makeMeasureSpec(Ui.dp(getTargetContext(),320),android.view.View.MeasureSpec.EXACTLY),android.view.View.MeasureSpec.makeMeasureSpec(0,android.view.View.MeasureSpec.UNSPECIFIED));entry.layout(0,0,entry.getMeasuredWidth(),entry.getMeasuredHeight());require(body.getLineCount()>=3,"multiline body is not flattened into a one-row button");android.widget.Button action=(android.widget.Button)entry.getChildAt(1);require(action.getMeasuredHeight()>=Ui.dp(getTargetContext(),44),"copy action preserves native touch target");action.performClick();require(raw.equals(accepted.get()),"native shared copy action receives original text, not preview");});
  result.putString("result","Passed");result.putInt("checks",checks);result.putBoolean("systemClipboardAccess",false);result.putBoolean("network",false);finish(-1,result);
 }catch(Throwable e){result.putString("result","Failed");result.putString("error",e.toString());result.putInt("checks",checks);finish(0,result);}}
}
